window.docContents[219].resolve({"/References/#Type-Systems--References___-Typing-Mutable-References--Definitions--Values-and-Substitution":{"contents":"Besides abstractions, numbers, and the unit value, we have one new\ntype of value: locations.\n\nA location is a concrete pointer value — think of it like an address\nin memory. Locations should never be written directly by programmers;\nthey are used to keep track of the intermediate states of programs\ninvolving references. In particular, the result of a ref expression\nis a location.\n\ninductive Tm.IsValue : Tm → Prop :=\n  | abs : forall x τ₂ t₁,\n      IsValue <{λx : τ₂. t₁}>\n  | nat : forall (n : Nat),\n      IsValue (.const n)\n  | unit :\n      IsValue <{ unit }>\n  | loc_ : forall (l : Nat),\n      IsValue (.loc l)\n\nattribute [StlcRefEval] Tm.IsValue.abs Tm.IsValue.nat Tm.IsValue.unit Tm.IsValue.loc_\n\n\nExtending substitution to handle the new syntax of terms is\nstraightforward: substituting into a pointer leaves it\nunchanged.\n\ndef subst (x : String) (s : Tm) (t : Tm) : Tm :=\n  match t with\n  -- pure STLC\n  | .var y =>\n      if x = y then s else t\n  | .abs y τ t₁ =>\n      if x = y then t else <{ λ y : τ . [x := s] t₁ }>\n  | .app t₁ t₂ =>\n      <{ ([x := s] t₁) ([x := s] t₂) }>\n  -- numbers\n  | .const _ =>\n      t\n  | .succ t₁ =>\n      <{ succ ([x := s] t₁) }>\n  | .pred t₁ =>\n      <{ pred ([x := s] t₁) }>\n  | .mult t₁ t₂ =>\n      <{ ([x := s] t₁) * ([x := s] t₂) }>\n  | .ite0 t₁ t₂ t₃ =>\n      <{\n        if0 [x := s] t₁\n        then [x := s] t₂\n        else [x := s] t₃\n      }>\n  -- unit\n  | .unit => <{ unit }>\n  -- references\n  | .ref t₁ =>  <{ ref ([x := s] t₁) }>\n  | .deref t₁ =>  <{ !([x := s] t₁) }>\n  | .loc n => .loc n\n  | .assign t₁ t₂ =>\n      <{ ([x := s] t₁) := ([x := s] t₂) }>\n\n\nopen Lean PrettyPrinter in\n@[app_unexpander subst]\ndef unexpandSubst : Unexpander := StlcCommon.Delab.unexpandSubst\n\n\n","context":"Type Systems\u0009References: Typing Mutable References\u0009Definitions","header":"9.1.5. Values and Substitution","id":"/References/#Type-Systems--References___-Typing-Mutable-References--Definitions--Values-and-Substitution"}});